// Fixtures for the Yarn 2+ (Berry) tests: project files, lockfiles and the
// table of refused projects. Shared by test/yarn-berry.test.js (bash, zsh),
// test/ps1-yarn-berry.test.js (PowerShell) and test/yarn-berry-helper.test.js.
const berryLock = (entries) =>
  [
    '# This file is generated by running "yarn install" inside your project.',
    "# Manual changes might be lost - proceed with caution!",
    "",
    "__metadata:",
    "  version: 8",
    "  cacheKey: 10c0",
    "",
    ...entries.flatMap(([key, version, resolution]) => [
      `"${key}":`,
      `  version: ${version}`,
      `  resolution: "${resolution}"`,
      "  languageName: node",
      "  linkType: hard",
      "",
    ]),
  ].join("\n");

const LOCK = berryLock([
  ["fixture@workspace:.", "0.0.0-use.local", "fixture@workspace:."],
]);
const PHASE1_LOCK = berryLock([
  ["fixture@workspace:.", "0.0.0-use.local", "fixture@workspace:."],
  ["ms@npm:^2.1.3", "2.1.3", "ms@npm:2.1.3"],
]);

// Lockfile sources the wrapper refuses. Yarn's git and GitHub fetchers
// download the source and run its scripts to pack it during phase 1, and
// exec: runs a script to make the package. Yarn rewrites the Yarn 1 git and
// GitHub shapes into #commit= sources when it reads the lockfile.
const SHA = "4ff48cec099f0514c3e9bbca18706c9c21122bfb";
const v1Lock = (resolved) =>
  `# yarn lockfile v1\n\n\nms@x:\n  version "2.1.3"\n  resolved "${resolved}"\n`;
const msLock = (resolution) => berryLock([["ms@x", "2.1.3", resolution]]);
const enc = encodeURIComponent;
const EVIL_TGZ = "https://evil.example/ms-2.1.3.tgz";
const NPM_TGZ = "https://registry.npmjs.org/ms/-/ms-2.1.3.tgz";
const ACME_TGZ = "https://npm.acme.example/@acme/x/-/x-1.0.0.tgz";
const SOURCE_LOCKS = [
  [
    "#commit=",
    berryLock([
      [
        "ms@github:vercel/ms",
        "2.1.3",
        `ms@https://github.com/vercel/ms.git#commit=${SHA}`,
      ],
    ]),
  ],
  [
    "patched, %23commit%3D",
    berryLock([
      [
        "ms@patch:ms@github:vercel/ms",
        "2.1.3",
        `ms@patch:ms@https%3A//github.com/vercel/ms.git%23commit%3D${SHA}#~/.yarn/patches/ms.patch`,
      ],
    ]),
  ],
  ["Yarn 1, git+https", v1Lock(`git+https://github.com/vercel/ms.git#${SHA}`)],
  [
    "Yarn 1, codeload",
    v1Lock(`https://codeload.github.com/vercel/ms/tar.gz/${SHA}`),
  ],
  ["Yarn 1, github.com#sha", v1Lock(`https://github.com/vercel/ms#${SHA}`)],
  [
    "Yarn 1, GitHub tarball, mixed case",
    v1Lock("https://GitHub.com/vercel/ms/tarball/v1"),
  ],
  ["Yarn 1, git://", v1Lock(`git://git.example.com/ms.git#${SHA}`)],
  ["Yarn 1, file:", v1Lock("file:./ms.tgz")],
  [
    "Yarn 1 from npm, quoted resolved",
    `# yarn lockfile v1\n\n\nms@x:\n  "resolved" "https://github.com/vercel/ms/tarball/v1"\n`,
  ],
  ["#head=", msLock("ms@https://github.com/vercel/ms.git#head=main")],
  ["no hash", msLock("ms@https://github.com/vercel/ms.git")],
  ["user/repo shorthand", msLock("ms@vercel/ms")],
  ["github:", msLock(`ms@github:vercel/ms#commit=${SHA}`)],
  ["ssh:", msLock(`ms@ssh://git@github.com/vercel/ms.git#commit=${SHA}`)],
  ["git@", msLock(`ms@git@github.com:vercel/ms.git#commit=${SHA}`)],
  [
    "a .git URL off GitHub",
    msLock(`ms@https://git.example.com/ms.GIT#commit=${SHA}`),
  ],
  ["exec:", msLock("ms@exec:./gen.js#::locator=fixture%40workspace%3A.")],
  ["http GitHub tarball", msLock("ms@http://github.com/vercel/ms/tarball/v1")],
  [
    "GitHub tarball with userinfo",
    msLock("ms@https://bob@github.com/vercel/ms/tarball/v1"),
  ],
  [
    "codeload",
    msLock(`ms@https://codeload.github.com/vercel/ms/tar.gz/${SHA}`),
  ],
  ["virtual:", msLock("ms@virtual:abc#npm:2.1.3")],
  ["a scoped github:", msLock("@acme/x@github:acme/x")],
  [
    "an encoded __archiveUrl name",
    msLock(`ms@npm:2.1.3::%5F%5FarchiveUrl=${enc(EVIL_TGZ)}`),
  ],
  [
    "a second __archiveUrl",
    msLock(
      `ms@npm:2.1.3::__archiveUrl=${enc(NPM_TGZ)}&__archiveUrl=${enc(EVIL_TGZ)}`,
    ),
  ],
  [
    "a patch of a package with an __archiveUrl",
    msLock(
      `ms@patch:ms@${enc(`npm:2.1.3::__archiveUrl=${enc(EVIL_TGZ)}`)}#~/.yarn/patches/ms.patch::version=2.1.3&hash=abc`,
    ),
  ],
];

// Lockfiles that download a package from a server ~/.yarnrc.yml does not
// name. Yarn sends the registry token with an npm: package's __archiveUrl
// download, and migrates a Yarn 1 resolved URL into one.
const ARCHIVE_LOCKS = [
  [
    "a scoped package",
    berryLock([
      [
        "@acme/x@npm:^1.0.0",
        "1.0.0",
        `@acme/x@npm:1.0.0::__archiveUrl=${enc(EVIL_TGZ)}`,
      ],
    ]),
  ],
  [
    "an unscoped package",
    msLock(`ms@npm:2.1.3::__archiveUrl=${enc(EVIL_TGZ)}`),
  ],
  [
    "a registry host as URL userinfo",
    msLock(
      `ms@npm:2.1.3::__archiveUrl=${enc("https://registry.npmjs.org@evil.example/ms.tgz")}`,
    ),
  ],
  [
    "http instead of https",
    msLock(
      `ms@npm:2.1.3::__archiveUrl=${enc(NPM_TGZ.replace("https", "http"))}`,
    ),
  ],
  [
    "a percent-encoded host",
    msLock(
      `ms@npm:2.1.3::__archiveUrl=${enc("https://registry%2enpmjs.org/ms.tgz")}`,
    ),
  ],
  [
    "a host with a trailing dot",
    msLock(
      `ms@npm:2.1.3::__archiveUrl=${enc("https://registry.npmjs.org./ms.tgz")}`,
    ),
  ],
  [
    "Yarn 1, a scoped tarball on another host",
    `# yarn lockfile v1\n\n\n"@acme/x@^1.0.0":\n  version "1.0.0"\n  resolved "https://evil.example/r/@acme/x/-/@acme/x-1.0.0.tgz"\n`,
  ],
];

// Lockfiles that are valid YAML (or Yarn 1 syntax) but not the plain layout
// Yarn writes, so a line-based check could misread them.
const LINES_LOCKS = [
  [
    "a flow mapping",
    `${LOCK}"ms@x": {version: 2.1.3, resolution: "ms@github:vercel/ms"}\n`,
  ],
  ["a quoted indent-2 key", `${LOCK}"ms@x":\n  "resolution": "ms@vercel/ms"\n`],
  [
    "a child under a key with a value",
    `${LOCK}"ms@x":\n  resolution: "ms@npm:2.1.3"\n    x: y\n`,
  ],
  ["an unterminated quote", `${LOCK}"ms@x":\n  resolution: "ms@npm:2.1.3\n`],
  ["a tab", `${LOCK}"ms@x":\n\tresolution: "ms@npm:2.1.3"\n`],
  ["a non-ASCII byte", `${LOCK}"ms@x":\n  version: 2.1.3\u00a0\n`],
  ["an explicit ? key", `${LOCK}? "ms@x"\n: {resolution: "ms@vercel/ms"}\n`],
  ["an anchor", `${LOCK}"ms@x":\n  resolution: &a "ms@npm:2.1.3"\n`],
  ["an alias", `${LOCK}"ms@x":\n  resolution: *a\n`],
  ["a backslash escape", `${LOCK}"ms@x":\n  resolution: "ms@vercel\\x2fms"\n`],
  ["a block scalar", `${LOCK}"ms@x":\n  resolution: >-\n    ms@vercel/ms\n`],
  ["a second document", `${LOCK}---\n"ms@x":\n  resolution: "ms@vercel/ms"\n`],
  ["a merge key", `${LOCK}"ms@x":\n  <<: *a\n`],
  ["a top-level key with a value", `${LOCK}"ms@x": ms@vercel/ms\n`],
  [
    "resolved in a Yarn 2+ lockfile",
    `${LOCK}"ms@x":\n  resolved: "ms@vercel/ms"\n`,
  ],
  [
    "__metadata in a Yarn 1 lockfile",
    `${v1Lock(NPM_TGZ)}__metadata:\n  version "8"\n`,
  ],
  [
    "resolution in a Yarn 1 lockfile",
    `# yarn lockfile v1\n\n\nms@x:\n  resolution "ms@vercel/ms"\n`,
  ],
];

// The shapes a real Yarn 4 lockfile has, all from sources the wrapper runs.
